with recursive cte0 (id,parentId,name,level,mqCycleMark,path) as (select fne1_0.id,fne1_0.parent_id,fne1_0.name,0,0,cast(concat(char(0 using ascii),coalesce(concat(fne1_0.id,''),char(0 using ascii)),char(0 using ascii),char(0 using ascii)) as char(22000)) from folder_nodes fne1_0 where fne1_0.id=? union all select fne2_0.id,fne2_0.parent_id,fne2_0.name,(cte01_0.level+cast(? as signed)),case when cte01_0.path like concat('%',replace(replace(replace(concat(char(0 using ascii),coalesce(concat(fne2_0.id,''),char(0 using ascii)),char(0 using ascii),char(0 using ascii)),'~','~~'),'?','~?'),'%','~%'),'%') escape '~' then 1 else 0 end,concat(cte01_0.path,char(0 using ascii),coalesce(concat(fne2_0.id,''),char(0 using ascii)),char(0 using ascii),char(0 using ascii)) from cte0 cte01_0,folder_nodes fne2_0 where fne2_0.parent_id=cte01_0.id and cte01_0.level<? and not(cte01_0.mqCycleMark)) select cte02_0.id,cte02_0.parentId,cte02_0.name,cte02_0.level,(select min(cte03_0.id) from cte0 cte03_0 where cte03_0.level>?),(select min(cte04_0.id) from cte0 cte04_0 where cte04_0.mqCycleMark) from cte0 cte02_0 where cte02_0.level<=? and not(cte02_0.mqCycleMark) order by 1
